insert into public.collections (id, name, tagline, summary, concept, image, tone, position) values
  ('boatoat', 'BoatOat FM Brasil 2026', 'Virou coisa nossa.', 'Coleção conceitual criada a partir de duas artes da Lilian, com os bordões “Tá bom!” e “Gostoso!”.', true, 'img/arte-ta-bom.webp', 'cream', 0),
  ('dorama-club', 'Dorama Club', 'Só mais um episódio.', 'Para quem maratona doramas com chá, lencinho e caderno de frases favoritas.', false, null, 'red', 1),
  ('sweet-memories', 'Sweet Memories', 'Para guardar o que faz sentir.', 'Papelaria e acessórios para colecionar photocards, ingressos e lembranças de K-pop e BTS.', false, null, 'lilac', 2),
  ('bl-diaries', 'BL Diaries', 'Toda história merece um final feliz.', 'Pequenos objetos para quem acompanha séries BL e coleciona casais favoritos.', false, null, 'yellow', 3),
  ('essenciais', 'Essenciais Fan Joy', 'A florzinha que acompanha você.', 'Itens com a identidade da loja, presentes prontos e materiais gratuitos.', false, null, 'navy', 4)
insert into public.products (id, name, category_id, collection_id, price, mode, stock, low_stock, production_days, featured, active, short, description, details, images, art, variations, personalization, weight_g, length_cm, width_cm, height_cm) values
  ('caneca-ta-bom', 'Caneca “Tá bom!”', 'canecas', 'boatoat', 50, 'pronta', 14, 5, 2, true, true, 'A resposta para tudo, agora no seu café.', 'Durante o fanmeeting, o Boat respondia “Tá bom!” para quase tudo. A Lilian transformou a lembrança numa estampa contínua que dá a volta inteira na caneca.', '["Cerâmica branca, 325 ml","Impressão por sublimação, cobre a caneca toda","Pode ir ao micro-ondas; lavar à mão preserva a arte por mais tempo","Arte original da Lilian. Coleção conceitual, sem vínculo oficial com os artistas, a produtora ou o evento."]'::jsonb, '[{"src":"img/arte-ta-bom.webp","alt":"Mockup de três canecas brancas com a arte “Tá bom!” da Lilian: lado esquerdo, meio e lado direito, e a faixa completa da estampa abaixo","fit":"contain"}]'::jsonb, null, '[{"name":"Modelo","options":[{"label":"Branca","add":0},{"label":"Colorida (alça e interior coloridos)","add":10},{"label":"Mágica (revela a arte com calor)","add":20}]}]'::jsonb, '{"label":"Nome na alça","max":12,"placeholder":"Ex.: Lilian"}'::jsonb, 400, 12, 12, 10),
  ('caneca-gostoso', 'Caneca “Gostoso!”', 'canecas', 'boatoat', 50, 'pronta', 3, 5, 2, true, true, 'Para quem foi chamado de fofo e respondeu à altura.', 'Quando os fãs chamavam o Oat de fofo, ele corrigia: “gostoso!”. A arte da Lilian guarda esse momento com corações e muita risada.', '["Cerâmica branca, 325 ml","Impressão por sublimação","Pode ir ao micro-ondas","Arte original da Lilian. Coleção conceitual, sem vínculo oficial com os artistas, a produtora ou o evento."]'::jsonb, '[{"src":"img/caneca-gostoso.webp","alt":"Caneca branca com a arte “Gostoso!” da Lilian, com seis personagens fazendo coração com as mãos","fit":"cover"}]'::jsonb, null, '[{"name":"Modelo","options":[{"label":"Branca","add":0},{"label":"Colorida (alça e interior coloridos)","add":10},{"label":"Mágica (revela a arte com calor)","add":20}]}]'::jsonb, '{"label":"Nome na alça","max":12,"placeholder":"Ex.: Mari"}'::jsonb, 400, 12, 12, 10),
  ('bottons-dupla', 'Dupla de bottons “Tá bom!” + “Gostoso!”', 'bottons', 'boatoat', 18.9, 'pronta', 40, 10, 1, true, true, 'Os dois bordões, lado a lado, na sua ecobag.', 'Um botton para cada bordão. Combina com mochila, ecobag e jaqueta de show.', '["2 bottons com alfinete de segurança","Acabamento brilhante","Arte original da Lilian. Coleção conceitual, sem vínculo oficial com os artistas, a produtora ou o evento."]'::jsonb, '[{"src":"img/bottons-dupla.webp","alt":"Dois bottons redondos: um com o personagem dizendo “Tá bom!” e outro dizendo “Gostoso!”","fit":"cover"}]'::jsonb, null, '[{"name":"Tamanho","options":[{"label":"38 mm","add":0},{"label":"58 mm","add":4}]}]'::jsonb, null, 50, 10, 10, 2),
  ('photocards', 'Kit de photocards “Virou coisa nossa”', 'photocards', 'boatoat', 24.9, 'encomenda', 0, 0, 7, true, true, 'Seis cards ilustrados para trocar, guardar e colecionar.', 'Três cards “Tá bom!” e três cards “Gostoso!”, no tamanho padrão de photocard. Produzidos sob encomenda para garantir o acabamento escolhido.', '["6 cards de 5,5 × 8,5 cm","Papel 300 g com cantos arredondados","Verso com a florzinha da Fan Joy","Arte original da Lilian. Coleção conceitual, sem vínculo oficial com os artistas, a produtora ou o evento."]'::jsonb, '[{"src":"img/photocards.webp","alt":"Seis photocards ilustrados pela Lilian: três com “Tá bom!” e três com “Gostoso!”","fit":"cover"}]'::jsonb, null, '[{"name":"Acabamento","options":[{"label":"Fosco","add":0},{"label":"Holográfico","add":8}]}]'::jsonb, null, 50, 12, 8, 2),
  ('ecobag-boatoat', 'Ecobag “Virou coisa nossa”', 'acessorios', 'boatoat', 59.9, 'pronta', 8, 4, 3, true, true, 'As duas artes juntas, para levar o fanmeeting no ombro.', 'Ecobag de algodão cru com as duas artes da coleção. Cabe caderno, garrafa e todos os seus photocards.', '["Algodão cru 100%, 38 × 42 cm","Alça de 60 cm","Lavar do avesso, em água fria","Arte original da Lilian. Coleção conceitual, sem vínculo oficial com os artistas, a produtora ou o evento."]'::jsonb, '[{"src":"img/ecobag.webp","alt":"Ecobag de algodão cru com as duas artes da Lilian: “Tá bom!” e “Gostoso!”","fit":"cover"}]'::jsonb, null, '[]'::jsonb, '{"label":"Frase no verso","max":20,"placeholder":"Ex.: Virou coisa nossa"}'::jsonb, 200, 30, 25, 3),
  ('adesivos-boatoat', 'Cartela de adesivos “Piadas do fandom”', 'papelaria', 'boatoat', 14.9, 'pronta', 25, 8, 1, true, true, 'Seis adesivos para o caderno, o notebook e a capinha.', 'Cartela com recorte individual. Os bordões do fanmeeting prontos para colar onde você quiser.', '["Cartela A6 com 6 adesivos","Vinil fosco resistente à água","Arte original da Lilian. Coleção conceitual, sem vínculo oficial com os artistas, a produtora ou o evento."]'::jsonb, '[{"src":"img/adesivos.webp","alt":"Cartela com seis adesivos recortados: três “Tá bom!” e três “Gostoso!”","fit":"cover"}]'::jsonb, null, '[]'::jsonb, null, 250, 23, 17, 3),
  ('banner-oat', 'Banner do Oat “Gostoso!”', 'banners', 'boatoat', 29.9, 'pronta', 6, 3, 2, true, true, 'A arte panorâmica inteira, pronta para levantar no show.', 'Banner em formato panorâmico com a arte “Gostoso!”. Entrou no lugar do antigo print e é o item mais novo da coleção.', '["Lona fosca com bastão e cordão","Leve para segurar com uma mão","Arte original da Lilian. Coleção conceitual, sem vínculo oficial com os artistas, a produtora ou o evento."]'::jsonb, '[{"src":"img/arte-gostoso.webp","alt":"Arte panorâmica da Lilian com seis versões do Oat dizendo “Gostoso!” entre corações","fit":"contain"}]'::jsonb, null, '[{"name":"Tamanho","options":[{"label":"60 × 26 cm","add":0},{"label":"90 × 38 cm","add":15}]}]'::jsonb, null, 250, 70, 10, 10),
  ('banner-boat', 'Banner do Boat “Tá bom!”', 'banners', 'boatoat', 29.9, 'pronta', 6, 3, 2, true, true, 'A frase favorita do Boat em letras grandes, para o show.', 'Banner panorâmico com seis versões do Boat e o “Tá bom” em destaque. Faz par com o banner do Oat “Gostoso!”.', '["Lona fosca com bastão e cordão","Leve para segurar com uma mão","Arte original da Lilian. Coleção conceitual, sem vínculo oficial com os artistas, a produtora ou o evento."]'::jsonb, '[{"src":"img/banner-boat.webp","alt":"Banner panorâmico da Lilian com seis versões do Boat segurando microfone, balões “Tá bom” e o letreiro “A frase favorita do Boat: Tá bom”","fit":"contain"}]'::jsonb, null, '[{"name":"Tamanho","options":[{"label":"60 × 27 cm","add":0},{"label":"90 × 40 cm","add":15}]}]'::jsonb, null, 250, 70, 10, 10),
  ('caneca-mais-um-episodio', 'Caneca “Só mais um episódio”', 'canecas', 'dorama-club', 50, 'pronta', 11, 4, 2, false, true, 'Para a maratona que começou às 22h e terminou às 4h.', 'Caneca para acompanhar o chá das maratonas de dorama.', '["Cerâmica branca, 325 ml","Arte demonstrativa: será substituída pela arte da Lilian"]'::jsonb, '[]'::jsonb, '{"kind":"mug","text":"só mais um\nepisódio","bg":"red"}'::jsonb, '[{"name":"Modelo","options":[{"label":"Branca","add":0},{"label":"Colorida (alça e interior vermelhos)","add":10},{"label":"Mágica (revela a arte com calor)","add":20}]}]'::jsonb, '{"label":"Nome","max":12,"placeholder":"Ex.: Ana"}'::jsonb, 400, 12, 12, 10),
  ('caderno-diario-dorama', 'Caderno “Diário de dorama” A5', 'papelaria', 'dorama-club', 36.9, 'pronta', 9, 4, 3, false, true, 'Notas, frases favoritas e a lista do que assistir.', 'Caderno com páginas para registrar doramas assistidos, notas e as falas que ficaram na memória.', '["A5, 80 folhas pontilhadas","Capa dura laminada","Arte demonstrativa"]'::jsonb, '[]'::jsonb, '{"kind":"notebook","text":"diário de\ndorama","bg":"cream"}'::jsonb, '[]'::jsonb, '{"label":"Nome na capa","max":16,"placeholder":"Ex.: Diário da Bia"}'::jsonb, 250, 23, 17, 3),
  ('marcadores-dorama', 'Kit de marcadores de página', 'papelaria', 'dorama-club', 12.9, 'pronta', 30, 8, 1, false, true, 'Quatro marcadores para o livro e o planner.', 'Kit com quatro marcadores ilustrados com frases de dorama.', '["4 marcadores de 5 × 15 cm","Papel 300 g com fita de cetim","Arte demonstrativa"]'::jsonb, '[]'::jsonb, '{"kind":"bookmarks","text":"fighting!","bg":"yellow"}'::jsonb, '[]'::jsonb, null, 250, 23, 17, 3),
  ('porta-photocard', 'Porta-photocard Sweet Memories', 'acessorios', 'sweet-memories', 22.9, 'pronta', 2, 4, 2, false, true, 'Protege seu card favorito e vai pendurado na bolsa.', 'Porta-photocard em acrílico com corrente, para levar o bias junto.', '["Acrílico transparente, 6 × 9 cm","Corrente com mosquetão","Arte demonstrativa"]'::jsonb, '[]'::jsonb, '{"kind":"holder","text":"sweet\nmemories","bg":"lilac"}'::jsonb, '[{"name":"Cor da corrente","options":[{"label":"Dourada","add":0},{"label":"Prata","add":0}]}]'::jsonb, null, 200, 30, 25, 3),
  ('kit-toploader', 'Kit de toploaders decorados', 'photocards', 'sweet-memories', 29.9, 'encomenda', 0, 0, 6, false, true, 'Três toploaders decorados à mão para seus cards.', 'Toploaders decorados com adesivos e glitter, montados um a um depois do pedido.', '["3 toploaders 35pt","Decoração feita à mão","Arte demonstrativa"]'::jsonb, '[]'::jsonb, '{"kind":"cards","text":"borahae\nmoments","bg":"lilac"}'::jsonb, '[{"name":"Paleta","options":[{"label":"Lilás","add":0},{"label":"Azul e amarelo","add":0}]}]'::jsonb, '{"label":"Nome do bias","max":14,"placeholder":"Ex.: nome do seu bias"}'::jsonb, 50, 12, 8, 2),
  ('chaveiro-bl', 'Chaveiro acrílico “Final feliz”', 'acessorios', 'bl-diaries', 19.9, 'encomenda', 0, 0, 8, false, true, 'Para quem torce pelo casal desde o primeiro episódio.', 'Chaveiro em acrílico com impressão dos dois lados, produzido sob encomenda.', '["Acrílico 3 mm, 6 cm","Impressão frente e verso","Arte demonstrativa"]'::jsonb, '[]'::jsonb, '{"kind":"keychain","text":"final\nfeliz","bg":"yellow"}'::jsonb, '[]'::jsonb, '{"label":"Nome do casal","max":18,"placeholder":"Ex.: nomes do seu casal"}'::jsonb, 200, 30, 25, 3),
  ('planner-bl', 'Planner semanal BL Diaries', 'papelaria', 'bl-diaries', 39.9, 'pronta', 7, 3, 3, false, true, 'Episódios novos toda semana? Anote aqui.', 'Planner sem datas com espaço para estreias, maratonas e metas da semana.', '["A5, 52 semanas sem data","Espiral dourado","Arte demonstrativa"]'::jsonb, '[]'::jsonb, '{"kind":"notebook","text":"bl\ndiaries","bg":"yellow"}'::jsonb, '[]'::jsonb, null, 250, 23, 17, 3),
  ('camiseta-little-joy', 'Camiseta Little Joy', 'camisetas', 'essenciais', 79.9, 'pronta', 12, 4, 4, false, true, 'A florzinha da Fan Joy no peito.', 'Camiseta de algodão com a florzinha sorridente da Fan Joy Store.', '["Algodão penteado 30.1","Modelagem unissex","Arte demonstrativa"]'::jsonb, '[]'::jsonb, '{"kind":"tee","text":"little joy","bg":"cream"}'::jsonb, '[{"name":"Tamanho","options":[{"label":"P","add":0},{"label":"M","add":0},{"label":"G","add":0},{"label":"GG","add":0}]},{"name":"Cor","options":[{"label":"Off-white","add":0},{"label":"Azul-marinho","add":0}]}]'::jsonb, null, 200, 25, 20, 3),
  ('fan-joy-box', 'Fan Joy Box', 'presentes', 'essenciais', 119.9, 'pronta', 4, 2, 3, false, true, 'Caixa presente com caneca, adesivos, marcador e cartão.', 'Presente pronto para aniversário ou amigo secreto. Você escolhe o fandom e a Lilian monta a caixa.', '["Caixa rígida com laço","Inclui caneca, cartela de adesivos, marcador e cartão escrito à mão","Arte demonstrativa"]'::jsonb, '[]'::jsonb, '{"kind":"box","text":"fan joy\nbox","bg":"navy"}'::jsonb, '[{"name":"Tema","options":[{"label":"Dorama","add":0},{"label":"K-pop","add":0},{"label":"BL","add":0}]}]'::jsonb, '{"label":"Mensagem do cartão","max":80,"placeholder":"Ex.: Feliz aniversário, Ju!"}'::jsonb, 900, 25, 25, 15),
  ('ecobag-everyday', 'Ecobag Everyday Fan', 'acessorios', 'essenciais', 54.9, 'pronta', 0, 3, 3, false, false, 'Esgotada. Nova tiragem em avaliação.', 'Ecobag com a florzinha da Fan Joy. Esgotou e está fora de linha até a próxima tiragem.', '["Algodão cru","Arte demonstrativa"]'::jsonb, '[]'::jsonb, '{"kind":"bag","text":"everyday\nfan","bg":"cream"}'::jsonb, '[]'::jsonb, null, 200, 30, 25, 3),
  ('wallpaper-fan-joy', 'Papel de parede Fan Joy', 'freebies', 'essenciais', 0, 'gratis', 0, 0, 0, false, true, 'Grátis para celular, em duas versões.', 'Papel de parede com a florzinha da Fan Joy para celular. Um presente da Lilian para a comunidade.', '["1170 × 2532 px","Uso pessoal, sem fins comerciais"]'::jsonb, '[]'::jsonb, '{"kind":"phone","text":"fan joy","bg":"red"}'::jsonb, '[]'::jsonb, null, null, null, null, null),
  ('kit-lettering', 'Folhas de lettering para imprimir', 'freebies', 'dorama-club', 0, 'gratis', 0, 0, 0, false, true, 'Pratique lettering com frases de dorama.', 'PDF gratuito com frases de dorama para praticar lettering em casa.', '["PDF A4, 4 páginas","Uso pessoal"]'::jsonb, '[]'::jsonb, '{"kind":"notebook","text":"saranghae","bg":"cream"}'::jsonb, '[]'::jsonb, null, null, null, null, null),
  ('brinde-equipe', 'Kit brinde corporativo', 'brindes', 'essenciais', null, 'orcamento', 0, 0, 15, false, true, 'Canecas, cadernos e ecobags com a sua marca, a partir de 20 unidades.', 'Kits para eventos, onboarding e datas comemorativas, com arte desenvolvida pela Lilian a partir da identidade da sua empresa.', '["A partir de 20 unidades","Arte exclusiva com aprovação antes da produção","Nota fiscal e entrega em lote"]'::jsonb, '[]'::jsonb, '{"kind":"box","text":"sua\nmarca","bg":"navy"}'::jsonb, '[]'::jsonb, null, null, null, null, null)
